{
  "name": "@signetai/connector-opencode",
  "version": "1.0.1",
  "description": "Signet connector for OpenCode - installs hooks and generates config",
  "type": "module",
  "main": "./dist/index.js",
  "types": "./dist/index.d.ts",
  "exports": {
    ".": {
      "import": "./dist/index.js",
      "types": "./dist/index.d.ts"
    }
  },
  "files": [
    "dist",
    "bin",
    "!dist/**/*.test.*",
    "!dist/**/__tests__/**"
  ],
  "scripts": {
    "build": "bun run build:bundle",
    "build:bundle": "bun scripts/embed-plugin.ts && bun build src/index.ts --outdir dist --target node --external better-sqlite3 --external @napi-rs/keyring && bun run build:types",
    "build:types": "tsc --emitDeclarationOnly --declaration --outDir dist",
    "dev": "bun --watch src/index.ts",
    "typecheck": "tsc --noEmit"
  },
  "dependencies": {
    "@signetai/connector-base": "1.0.1",
    "@signetai/core": "1.0.1",
    "jsonc-parser": "3.3.1"
  },
  "devDependencies": {
    "@signet/opencode-plugin": "workspace:*",
    "@types/node": "^22.0.0",
    "typescript": "^5.7.0"
  },
  "keywords": [
    "signet",
    "opencode",
    "connector",
    "ai-memory",
    "agent-identity"
  ],
  "license": "Apache-2.0",
  "bin": {
    "signet-connector-opencode": "bin/install.js"
  },
  "publishConfig": {
    "access": "public"
  },
  "repository": {
    "type": "git",
    "url": "git+https://github.com/Signet-AI/signetai.git"
  },
  "homepage": "https://github.com/Signet-AI/signetai",
  "bugs": {
    "url": "https://github.com/Signet-AI/signetai/issues"
  }
}
